<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import AuditTextValue from './AuditTextValue.vue';
import { auditJsonChildren, auditJsonSummary, type AuditJsonValue } from './audit-preview-model';
const props=defineProps<{value:AuditJsonValue;label?:string;depth?:number}>();
const level=computed(()=>props.depth??0);const expanded=ref(level.value===0);
const children=computed(()=>auditJsonChildren(props.value));const container=computed(()=>typeof props.value==='object'&&props.value!==null);
watch(()=>props.value,()=>{expanded.value=level.value===0;});
function toggle(event:Event):void{if(event.target===event.currentTarget&&event.target instanceof HTMLDetailsElement)expanded.value=event.target.open;}
</script>
<template><details v-if="container" class="audit-json-container" :open="expanded" @toggle="toggle"><summary><strong v-if="label">{{label}}</strong><span>{{auditJsonSummary(value)}}</span></summary><div v-if="expanded" class="audit-json-children"><template v-if="level<8"><AuditJsonValue v-for="child in children.slice(0,80)" :key="child.key" :value="child.value" :label="child.key" :depth="level+1"/><p v-if="children.length>80">还有 {{children.length-80}} 项。切换到“格式化 JSON”可查看全部已保存字段。</p><p v-if="!children.length">（空{{Array.isArray(value)?'数组':'对象'}}）</p></template><AuditTextValue v-else :text="JSON.stringify(value,null,2)" monospace/></div></details><div v-else class="audit-json-leaf"><strong v-if="label">{{label}}</strong><AuditTextValue v-if="typeof value==='string'" :text="value"/><code v-else>{{value===null?'null':String(value)}}</code></div></template>
<style scoped>.audit-json-container,.audit-json-leaf{min-width:0}.audit-json-container>summary{display:flex;align-items:baseline;flex-wrap:wrap;gap:9px;cursor:pointer;font-size:12px;line-height:1.7;padding:6px 0}.audit-json-container>summary::before{content:'▸';color:var(--muted)}.audit-json-container[open]>summary::before{content:'▾'}.audit-json-container strong,.audit-json-leaf>strong{font:500 11px/1.7 ui-monospace,SFMono-Regular,Menlo,monospace;overflow-wrap:anywhere;color:var(--ink)}.audit-json-container summary>span,.audit-json-children>p{font-size:11px;color:var(--muted)}.audit-json-children{padding-left:14px;border-left:1px solid var(--line);display:grid;gap:7px;margin:2px 0 6px 4px}.audit-json-leaf{display:grid;grid-template-columns:minmax(60px,140px) minmax(0,1fr);gap:8px;border-bottom:1px solid var(--line);padding:8px 0}.audit-json-leaf:not(:has(>strong)){grid-template-columns:1fr}.audit-json-leaf>code{font-size:12px;color:var(--accent-ink);overflow-wrap:anywhere}@media(max-width:600px){.audit-json-leaf{grid-template-columns:1fr;gap:3px}.audit-json-children{padding-left:9px}}</style>
